// StartFit privacy policy. One source for the in-app page (/privacy) and the public HTML file
// (public/privacy.html, generated by scripts/generate-privacy-html.mjs).
//
// Written from what the app's code actually does. Items in [[double brackets]] are facts only the app owner
// can supply (who they are, contact details, hosting region, minimum age, backup period, transfer safeguard);
// fill them in before publishing — see PLACEHOLDERS below.

import { PRIVACY_POLICY_VERSION } from './version';

export const PLACEHOLDERS = {
  CONTROLLER: '[[Your full legal name or registered company name]]',
  ADDRESS: '[[Postal address]]',
  EMAIL: '[[Privacy contact email address]]',
  MIN_AGE: '[[Minimum age, e.g. 16]]',
  REGION: '[[Supabase project region, e.g. London (eu-west-2)]]',
  BACKUP_DAYS: '[[Number of days your Supabase plan keeps backups]]',
  TRANSFERS: '[[Transfer safeguard for US providers — confirm in each provider’s data processing agreement, e.g. the UK International Data Transfer Addendum or the UK Extension to the EU–US Data Privacy Framework]]',
} as const;

export interface PolicySection {
  id: string;
  title: string;
  paragraphs?: string[];
  bullets?: string[];
  table?: { head: string[]; rows: string[][] };
}

const P = PLACEHOLDERS;

